B.a9L={"ctrl.if":0,"ctrl.else":1,"ctrl.while":2,"ctrl.for_range":3,"ctrl.foreach":4,"ctrl.break":5,"ctrl.continue":6,"ctrl.return":7,"fn.def":8,"fn.call":9,"fn.call1":10,"fn.call2":11,"fn.call3":12,"fn.call4":13,"fn.call5":14,"fn.call6":15,"var.set":16,"var.get":17,"var.inc":18,"var.dec":19,"lit.num":20,"lit.bool":21,"lit.null":22,"cmp.eq":23,"cmp.ne":24,"cmp.lt":25,"cmp.le":26,"cmp.gt":27,"cmp.ge":28,"logic.and":29,"logic.or":30,"logic.not":31,"logic.is_nothing":32,"logic.is_not_nothing":33,"arith.add":34,"arith.sub":35,"arith.mul":36,"arith.div":37,"arith.floor_div":38,"arith.mod":39,"arith.min":40,"arith.max":41,"arith.abs":42,"arr.get":43,"arr.set":44,"arr.len":45,"arr.append":46,"arr.remove":47,"arr.swap":48,"new.array":49,"map.get":50,"map.set":51,"map.has":52,"map.remove":53,"map.size":54,"new.map":55,"set.add":56,"set.has":57,"set.remove":58,"set.size":59,"new.set":60,"stack.push":61,"stack.pop":62,"stack.peek":63,"stack.empty":64,"new.stack":65,"queue.enq":66,"queue.deq":67,"queue.front":68,"queue.empty":69,"new.queue":70,"new.min_heap":71,"new.max_heap":72,"heap.insert":73,"heap.take":74,"heap.top":75,"heap.size":76,"heap.empty":77,"ll.value":78,"ll.next":79,"ll.set_next":80,"tree.value":81,"tree.left":82,"tree.right":83,"graph.neighbors":84,"graph.mark":85,"graph.visited":86,"graph.node_count":87,"lit.str":88,"str.len":89,"str.char_at":90,"str.concat":91,"str.substring":92,"str.compare":93,"str.from_num":94,"str.to_num":95,"arr.sort":96,"var.copy":97,"new.deque":98,"deque.push_front":99,"deque.push_back":100,"deque.pop_front":101,"deque.pop_back":102,"deque.front":103,"deque.back":104,"deque.size":105,"deque.empty":106,"pair.make":107,"pair.first":108,"pair.second":109}
B.UB=new A.ac("IF","E\u011eER / KO\u015eUL","Checks a condition. The blocks inside THEN run only when the condition is true. ADD ELSE gives a second list that runs when it is false.","Bir ko\u015fulu kontrol eder. Ko\u015ful do\u011fruysa THEN i\xe7indeki bloklar \xe7al\u0131\u015ft\u0131r\u0131l\u0131r. ADD ELSE, ko\u015ful yanl\u0131\u015fsa \xe7al\u0131\u015fan ikinci bir liste ekler.","IF x GREATER THAN 3\n  THEN  SET found TO TRUE\n  ELSE  SET found TO FALSE",null)
B.U4=new A.ac("ELSE","DE\u011e\u0130LSE","The second branch of an IF: its blocks run when the condition is false.","IF blo\u011funun ikinci dal\u0131: ko\u015ful yanl\u0131\u015fsa buradaki bloklar \xe7al\u0131\u015f\u0131r.","IF c IS NOTHING\n  THEN  SET total TO 1\n  ELSE  SET total TO c PLUS 1",null)
B.Uk=new A.ac("WHILE","\u0130KEN / D\xd6NG\xdc","Repeats the blocks inside DO for as long as the condition stays true. Something inside must change, or the loop never ends.","Ko\u015ful do\u011fru kald\u0131\u011f\u0131 s\xfcrece DO i\xe7indeki bloklar\u0131 tekrar eder. \u0130\xe7eride bir \u015fey de\u011fi\u015fmeli, yoksa d\xf6ng\xfc hi\xe7 bitmez.","SET i TO 0\nWHILE i LESS THAN (nums LENGTH)\n  DO  INCREMENT i",null)
B.V6=new A.ac("FOR","SAYARAK D\xd6NG\xdc","Counts a variable FROM a start number TO an end number (the end is not included), BY a step, and runs DO once for each value.","Bir de\u011fi\u015fkeni ba\u015flang\u0131\xe7 say\u0131s\u0131ndan (FROM) biti\u015f say\u0131s\u0131na (TO, biti\u015f dahil de\u011fil) ad\u0131m (BY) kadar sayar ve her de\u011fer i\xe7in DO k\u0131sm\u0131n\u0131 bir kez \xe7al\u0131\u015ft\u0131r\u0131r.","FOR i FROM 0 TO (nums LENGTH) BY 1\n  DO  SET total TO total PLUS (nums GET ELEMENT i)",null)
B.Ul=new A.ac("FOR EACH","HER B\u0130R\u0130 \u0130\xc7\u0130N","Takes the items of a list one by one, in order, puts each into a variable, and runs DO for it. The variable holds the item's value, not its position.","Bir listenin \xf6\u011felerini s\u0131rayla tek tek al\u0131r, her birini bir de\u011fi\u015fkene koyar ve DO k\u0131sm\u0131n\u0131 onun i\xe7in \xe7al\u0131\u015ft\u0131r\u0131r. De\u011fi\u015fken \xf6\u011fenin konumunu de\u011fil, de\u011ferini tutar.","FOR EACH r IN readings\n  DO  IF r GREATER THAN limit\n        THEN  INCREMENT count",null)
B.TW=new A.ac("BREAK","D\xd6NG\xdcDEN \xc7IK","Leaves the innermost loop at once; the program continues after that loop.","\u0130\xe7inde bulundu\u011fu en yak\u0131n d\xf6ng\xfcden hemen \xe7\u0131kar; program o d\xf6ng\xfcn\xfcn arkas\u0131ndan devam eder.","FOR EACH x IN nums\n  DO  IF x EQUAL 0\n        THEN  BREAK",null)
B.Uq=new A.ac("CONTINUE","SONRAK\u0130 TURA GE\xc7","Skips the rest of this round of the loop and goes on with the next round.","D\xf6ng\xfcn\xfcn bu turunun geri kalan\u0131n\u0131 atlar ve bir sonraki tura ge\xe7er.","FOR EACH x IN nums\n  DO  IF x LESS THAN 0\n        THEN  CONTINUE",null)
B.Uf=new A.ac("RETURN","D\xd6ND\xdcR","Ends the program and gives back its answer. The answer must be what the puzzle asks for (RETURNS in the brief). Inside a FUNCTION it ends only that function and gives its value back to the CALL.","Program\u0131 bitirir ve cevab\u0131n\u0131 geri verir. Cevap bulmacan\u0131n istedi\u011fi \u015fey olmal\u0131 (g\xf6revdeki D\xd6ND\xdcR\xdcR). Bir FUNCTION i\xe7inde yaln\u0131zca o fonksiyonu bitirir ve de\u011ferini CALL'a geri verir.","RETURN count",null)
B.UO=new A.ac("FUNCTION","FONKS\u0130YON","A function the puzzle asks you to write: its name and the values it takes are given. Build its steps inside it; RETURN gives its answer back to whoever CALLed it. A function may CALL itself: give it a case that RETURNs without calling again, or it never ends.","Bulmacan\u0131n senden yazman\u0131 istedi\u011fi bir fonksiyon: ad\u0131 ve ald\u0131\u011f\u0131 de\u011ferler verilmi\u015ftir. Ad\u0131mlar\u0131n\u0131 i\xe7ine kur; RETURN cevab\u0131n\u0131 onu CALL ile \xe7a\u011f\u0131rana geri verir. Bir fonksiyon kendini de CALL ile \xe7a\u011f\u0131rabilir: ona yeniden \xe7a\u011f\u0131rmadan RETURN eden bir durum ver, yoksa hi\xe7 bitmez.","FUNCTION fact (k)\n  IF k LESS OR EQUAL 1\n    THEN  RETURN 1\n  RETURN k TIMES CALL fact (k MINUS 1)",null)
B.eJ=new A.ac("CALL","\xc7A\u011eIR","Runs a FUNCTION with the values in its slots and stands for the value it RETURNs. Every call has its own variables; a list passed in is the same list, not a copy.","Bir FUNCTION'\u0131 yuvalar\u0131ndaki de\u011ferlerle \xe7al\u0131\u015ft\u0131r\u0131r ve onun RETURN etti\u011fi de\u011ferin yerine ge\xe7er. Her \xe7a\u011fr\u0131n\u0131n kendi de\u011fi\u015fkenleri vard\u0131r; i\xe7eri verilen bir liste kopya de\u011fil, ayn\u0131 listedir.","RETURN CALL fact (n)",null)
B.TJ=new A.ac("SET","ATA","Puts a value into a variable, replacing what it held. Tap the name to choose the variable.","Bir de\u011fi\u015fkene bir de\u011fer koyar; eski de\u011ferin yerine ge\xe7er. De\u011fi\u015fkeni se\xe7mek i\xe7in ada dokun.","SET best TO 0\nSET best TO best MAX x",null)
B.U9=new A.ac("a name","DE\u011e\u0130\u015eKEN\u0130 OKU","A name in a slot, like readings or count, reads what that variable holds right now. Tap a name under GIVENS or VARIABLES to put it in the selected slot.","Bir yuvadaki ad (\xf6r. readings ya da count), o de\u011fi\u015fkenin \u015fu anki de\u011ferini okur. Se\xe7ili yuvaya koymak i\xe7in VER\u0130LENLER ya da DE\u011e\u0130\u015eKENLER alt\u0131ndaki bir ada dokun.","RETURN count",null)
B.Vb=new A.ac("INCREMENT","B\u0130R ARTIR","Adds 1 to a number variable. Same as SET x TO x PLUS 1.","Say\u0131 tutan bir de\u011fi\u015fkene 1 ekler. SET x TO x PLUS 1 ile ayn\u0131d\u0131r.","INCREMENT count",null)
B.Ts=new A.ac("DECREMENT","B\u0130R AZALT","Takes 1 away from a number variable. Same as SET x TO x MINUS 1.","Say\u0131 tutan bir de\u011fi\u015fkenden 1 \xe7\u0131kar\u0131r. SET x TO x MINUS 1 ile ayn\u0131d\u0131r.","DECREMENT hi",null)
B.TK=new A.ac("NUMBER","SAYI","A fixed whole number. Tap it to type another one on the number pad; +/\u2212 makes it negative.","Sabit bir tam say\u0131. Ba\u015fka bir say\u0131 yazmak i\xe7in dokun; +/\u2212 onu negatif yapar.","SET count TO 0",null)
B.TV=new A.ac("TRUE / FALSE","DO\u011eRU / YANLI\u015e","A yes / no value: TRUE or FALSE. Tap it to choose the other one.","Evet / hay\u0131r de\u011feri: TRUE (do\u011fru) ya da FALSE (yanl\u0131\u015f). Di\u011ferini se\xe7mek i\xe7in dokun.","RETURN FALSE",null)
B.Tz=new A.ac("NOTHING","H\u0130\xc7B\u0130R \u015eEY / BO\u015e",'The empty value: no node, no answer found. Used for "no next car" or "nothing here yet".','Bo\u015f de\u011fer: d\xfc\u011f\xfcm yok, cevap bulunamad\u0131. "Sonraki vagon yok" ya da "burada hen\xfcz bir \u015fey yok" i\xe7in kullan\u0131l\u0131r.',"SET prev TO NOTHING",null)
B.TE=new A.ac("EQUAL","E\u015e\u0130T","TRUE when both sides are the same value.","\u0130ki taraf ayn\u0131 de\u011ferse TRUE olur.","IF (x REMAINDER 2) EQUAL 0",null)
B.UR=new A.ac("NOT EQUAL","E\u015e\u0130T DE\u011e\u0130L","TRUE when the two sides are different.","\u0130ki taraf farkl\u0131ysa TRUE olur.","IF here NOT EQUAL goal",null)
B.Us=new A.ac("LESS THAN","K\xdc\xc7\xdcKT\xdcR","TRUE when the left number is smaller than the right one.","Soldaki say\u0131 sa\u011fdakinden k\xfc\xe7\xfckse TRUE olur.","WHILE i LESS THAN (nums LENGTH)",null)
B.TC=new A.ac("LESS OR EQUAL","K\xdc\xc7\xdcK YA DA E\u015e\u0130T","TRUE when the left number is smaller than or equal to the right one.","Soldaki say\u0131 sa\u011fdakinden k\xfc\xe7\xfck ya da ona e\u015fitse TRUE olur.","WHILE lo LESS OR EQUAL hi",null)
B.TF=new A.ac("GREATER THAN","B\xdcY\xdcKT\xdcR","TRUE when the left number is larger than the right one. Equal is not greater.","Soldaki say\u0131 sa\u011fdakinden b\xfcy\xfckse TRUE olur. E\u015fit olmak b\xfcy\xfck olmak de\u011fildir.","IF r GREATER THAN limit",null)
B.Ty=new A.ac("GREATER OR EQUAL","B\xdcY\xdcK YA DA E\u015e\u0130T","TRUE when the left number is larger than or equal to the right one.","Soldaki say\u0131 sa\u011fdakinden b\xfcy\xfck ya da ona e\u015fitse TRUE olur.","IF total GREATER OR EQUAL quota",null)
B.Uv=new A.ac("AND","VE","TRUE only when both conditions are true. If the left one is false, the right one is not even checked.","Yaln\u0131zca iki ko\u015ful da do\u011fruysa TRUE olur. Sol taraf yanl\u0131\u015fsa sa\u011f taraf hi\xe7 kontrol edilmez.","IF (node IS NOT NOTHING) AND ((node NODE VALUE) EQUAL bad)",null)
B.UG=new A.ac("OR","VEYA","TRUE when at least one of the two conditions is true. If the left one is true, the right one is not checked.","\u0130ki ko\u015fuldan en az biri do\u011fruysa TRUE olur. Sol taraf do\u011fruysa sa\u011f taraf kontrol edilmez.","IF (x LESS THAN 0) OR (x GREATER THAN 9)",null)
B.Vh=new A.ac("NOT","DE\u011e\u0130L","Turns TRUE into FALSE and FALSE into TRUE.","TRUE'yu FALSE'a, FALSE'u TRUE'ya \xe7evirir.","WHILE NOT (line IS EMPTY)",null)
B.Ub=new A.ac("IS NOTHING","BO\u015e MU","TRUE when a value that may be empty is empty (NOTHING). In the ELSE of such an IF, the value is known to be there.","Bo\u015f olabilecek bir de\u011fer bo\u015fsa (NOTHING) TRUE olur. B\xf6yle bir IF'in ELSE k\u0131sm\u0131nda de\u011ferin var oldu\u011fu bilinir.","SET c TO (counts GET x)\nIF c IS NOTHING\n  THEN  PUT counts x 1",null)
B.TN=new A.ac("IS NOT NOTHING","BO\u015e DE\u011e\u0130L M\u0130","TRUE when a value that may be empty holds something. Inside the THEN (or the WHILE), the value can be used safely.","Bo\u015f olabilecek bir de\u011fer bir \u015fey tutuyorsa TRUE olur. THEN (ya da WHILE) i\xe7inde de\u011fer g\xfcvenle kullan\u0131labilir.","WHILE node IS NOT NOTHING\n  DO  SET node TO (node NEXT NODE)",null)
B.US=new A.ac("PLUS","ARTI","Adds two numbers.","\u0130ki say\u0131y\u0131 toplar.","SET total TO total PLUS x",null)
B.UQ=new A.ac("MINUS","EKS\u0130","Takes the right number away from the left one.","Sa\u011fdaki say\u0131y\u0131 soldakinden \xe7\u0131kar\u0131r.","SET need TO tuning MINUS x",null)
B.TR=new A.ac("TIMES","\xc7ARPI","Multiplies two numbers.","\u0130ki say\u0131y\u0131 \xe7arpar.","SET area TO width TIMES h",null)
B.TD=new A.ac("DIVIDE","B\xd6L\xdc","Divides the left number by the right one and drops what is left over, so the result is a whole number: 7 DIVIDE 2 is 3, and -7 DIVIDE 2 is -3. Dividing by zero is an error.","Soldaki say\u0131y\u0131 sa\u011fdakine b\xf6ler ve kalan\u0131 atar; sonu\xe7 tam say\u0131d\u0131r: 7 DIVIDE 2 sonucu 3, -7 DIVIDE 2 sonucu -3't\xfcr. S\u0131f\u0131ra b\xf6lmek hatad\u0131r.","SET half TO total DIVIDE 2",null)
B.V_=new A.ac("FLOOR DIVIDE","TAM B\xd6LME","Divides and rounds down to a whole number; 7 FLOOR DIVIDE 2 is 3. Good for a middle position. It differs from DIVIDE only below zero: -7 FLOOR DIVIDE 2 is -4, -7 DIVIDE 2 is -3.","B\xf6ler ve sonucu a\u015fa\u011f\u0131 yuvarlayarak tam say\u0131 yapar; 7 FLOOR DIVIDE 2 sonucu 3't\xfcr. Orta konumu bulmak i\xe7in uygundur. DIVIDE'dan yaln\u0131zca s\u0131f\u0131r\u0131n alt\u0131nda ayr\u0131l\u0131r: -7 FLOOR DIVIDE 2 sonucu -4, -7 DIVIDE 2 sonucu -3't\xfcr.","SET mid TO (lo PLUS hi) FLOOR DIVIDE 2",null)
B.UC=new A.ac("REMAINDER","KALAN (MOD)","What is left after dividing; 7 REMAINDER 2 is 1. (x REMAINDER 2) EQUAL 0 means x is even.","B\xf6lmeden sonra kalan; 7 REMAINDER 2 sonucu 1'dir. (x REMAINDER 2) EQUAL 0, x \xe7ift demektir.","IF (x REMAINDER 2) EQUAL 0",null)
B.TL=new A.ac("MIN","EN K\xdc\xc7\xdcK","The smaller of two numbers.","\u0130ki say\u0131dan k\xfc\xe7\xfck olan\u0131.","SET low TO low MIN balance",null)
B.UT=new A.ac("MAX","EN B\xdcY\xdcK","The larger of two numbers.","\u0130ki say\u0131dan b\xfcy\xfck olan\u0131.","SET best TO best MAX total",null)
B.Uc=new A.ac("ABSOLUTE","MUTLAK DE\u011eER","The number without its minus sign; ABSOLUTE \u22124 is 4.","Say\u0131n\u0131n eksi i\u015fareti olmadan h\xe2li; ABSOLUTE \u22124 sonucu 4't\xfcr.","SET gap TO ABSOLUTE (a MINUS b)",null)
B.UN=new A.ac("GET ELEMENT","\xd6\u011eEY\u0130 AL","The value at a position (index) in a list. Positions start at 0: nums GET ELEMENT 0 is the first item. The position is not the value.","Bir listede belirli bir konumdaki (index) de\u011fer. Konumlar 0'dan ba\u015flar: nums GET ELEMENT 0 ilk \xf6\u011fedir. Konum, de\u011ferin kendisi de\u011fildir.","SET x TO (readings GET ELEMENT i)",null)
B.UJ=new A.ac("SET ELEMENT","\xd6\u011eEY\u0130 DE\u011e\u0130\u015eT\u0130R","Replaces the value at a position in a list. Slots: the list, the position, the new value.","Listede bir konumdaki de\u011feri de\u011fi\u015ftirir. Yuvalar: liste, konum, yeni de\u011fer.","SET ELEMENT dist next (d PLUS 1)",null)
B.V4=new A.ac("LENGTH","UZUNLUK","How many items a list holds. The last position is one less: (nums LENGTH) MINUS 1.","Listenin ka\xe7 \xf6\u011fe tuttu\u011fu. Son konum bir eksi\u011fidir: (nums LENGTH) MINUS 1.","WHILE i LESS THAN (nums LENGTH)",null)
B.Ua=new A.ac("APPEND","SONA EKLE","Adds a value at the end of a list. Slots: the list, the value.","Listenin sonuna bir de\u011fer ekler. Yuvalar: liste, de\u011fer.","APPEND result x",null)
B.Tw=new A.ac("REMOVE AT","KONUMDAN S\u0130L","Removes the item at a position; the items after it move one place forward.","Bir konumdaki \xf6\u011feyi siler; ondan sonraki \xf6\u011feler bir yer \xf6ne kayar.","REMOVE AT line 0",null)
B.Ve=new A.ac("SWAP ELEMENTS","\xd6\u011eELER\u0130N YER\u0130N\u0130 DE\u011e\u0130\u015eT\u0130R","Exchanges the items at two positions of a list.","Listede iki konumdaki \xf6\u011felerin yerini de\u011fi\u015ftirir.","SWAP ELEMENTS nums i j",null)
B.UW=new A.ac("NEW LIST","YEN\u0130 L\u0130STE","A new, empty list to fill with APPEND.","APPEND ile doldurulacak yeni ve bo\u015f bir liste.","SET result TO NEW LIST",null)
B.TZ=new A.ac("GET (map)","E\u015eLEMEDEN AL","The value stored for a key in a map, or NOTHING if the key is not there yet. Check it with IS NOTHING.","Bir e\u015flemede bir anahtar i\xe7in saklanan de\u011fer; anahtar hen\xfcz yoksa NOTHING. IS NOTHING ile kontrol et.","SET c TO (counts GET x)",null)
B.V5=new A.ac("PUT","E\u015eLEMEYE KOY","Stores a value for a key in a map, replacing the old one. Slots: the map, the key, the value.","Bir e\u015flemede bir anahtar i\xe7in de\u011fer saklar; eskisinin yerine ge\xe7er. Yuvalar: e\u015fleme, anahtar, de\u011fer.","PUT counts x (c PLUS 1)",null)
B.Uy=new A.ac("HAS KEY","ANAHTAR VAR MI","TRUE when the map holds a value for the key.","E\u015fleme o anahtar i\xe7in bir de\u011fer tutuyorsa TRUE olur.","IF counts HAS KEY x",null)
B.UL=new A.ac("REMOVE KEY","ANAHTARI S\u0130L","Removes a key (and its value) from a map.","Bir anahtar\u0131 (ve de\u011ferini) e\u015flemeden siler.","REMOVE KEY counts kind",null)
B.TO=new A.ac("SIZE (map)","E\u015eLEME BOYUTU","How many keys a map holds.","E\u015flemenin ka\xe7 anahtar tuttu\u011fu.","WHILE (counts SIZE) GREATER THAN k",null)
B.UY=new A.ac("NEW MAP","YEN\u0130 E\u015eLEME","A new, empty map (key \u2192 value).","Yeni ve bo\u015f bir e\u015fleme (anahtar \u2192 de\u011fer).","SET counts TO NEW MAP",null)
B.TU=new A.ac("ADD","K\xdcMEYE EKLE","Adds a value to a set. A set holds each value at most once.","Bir k\xfcmeye de\u011fer ekler. K\xfcme her de\u011feri en fazla bir kez tutar.","ADD seen x",null)
B.Va=new A.ac("HAS","K\xdcMEDE VAR MI","TRUE when the value is in the set. Asking costs one step, however big the set is.","De\u011fer k\xfcmedeyse TRUE olur. Sormak, k\xfcme ne kadar b\xfcy\xfck olursa olsun tek ad\u0131m tutar.","IF seen HAS need",null)
B.UM=new A.ac("REMOVE","K\xdcMEDEN S\u0130L","Removes a value from a set.","K\xfcmeden bir de\u011feri siler.","REMOVE seen x",null)
B.Vk=new A.ac("SIZE (set)","K\xdcME BOYUTU","How many values a set holds.","K\xfcmenin ka\xe7 de\u011fer tuttu\u011fu.","RETURN (seen SIZE)",null)
B.Vc=new A.ac("NEW SET","YEN\u0130 K\xdcME","A new, empty set.","Yeni ve bo\u015f bir k\xfcme.","SET seen TO NEW SET",null)
B.U2=new A.ac("PUSH","YI\u011eINA KOY","Puts a value on top of a stack. The last one in is the first one out.","Bir y\u0131\u011f\u0131n\u0131n \xfcst\xfcne de\u011fer koyar. Son giren ilk \xe7\u0131kar.","PUSH open c",null)
B.TB=new A.ac("POP","YI\u011eINDAN AL","Takes the top value off a stack and gives it. An empty stack is an error: check IS EMPTY first.","Y\u0131\u011f\u0131n\u0131n \xfcst\xfcndeki de\u011feri \xe7\u0131kar\u0131r ve verir. Bo\u015f y\u0131\u011f\u0131n hatad\u0131r: \xf6nce IS EMPTY ile kontrol et.","SET top TO (waiting POP)",null)
B.TM=new A.ac("PEEK","\xdcSTE BAK","The top value of a stack, without taking it off.","Y\u0131\u011f\u0131n\u0131n \xfcst\xfcndeki de\u011fer; \xe7\u0131karmadan bakar.","IF (st PEEK) GREATER THAN h",null)
B.UE=new A.ac("IS EMPTY (stack)","YI\u011eIN BO\u015e MU","TRUE when the stack holds nothing.","Y\u0131\u011f\u0131n hi\xe7bir \u015fey tutmuyorsa TRUE olur.","IF open IS EMPTY\n  THEN  RETURN FALSE",null)
B.Um=new A.ac("NEW STACK","YEN\u0130 YI\u011eIN","A new, empty stack.","Yeni ve bo\u015f bir y\u0131\u011f\u0131n.","SET open TO NEW STACK",null)
B.Tr=new A.ac("ENQUEUE","KUYRU\u011eA EKLE","Adds a value at the back of a queue. The first one in is the first one out.","Kuyru\u011fun arkas\u0131na de\u011fer ekler. \u0130lk giren ilk \xe7\u0131kar.","ENQUEUE line start",null)
B.U_=new A.ac("DEQUEUE","KUYRUKTAN AL","Takes the front value out of a queue and gives it. Check IS EMPTY first.","Kuyru\u011fun \xf6n\xfcndeki de\u011feri \xe7\u0131kar\u0131r ve verir. \xd6nce IS EMPTY ile kontrol et.","SET here TO (line DEQUEUE)",null)
B.V3=new A.ac("FRONT","\xd6NE BAK","The front value of a queue, without taking it out.","Kuyru\u011fun \xf6n\xfcndeki de\u011fer; \xe7\u0131karmadan bakar.","IF (line FRONT) EQUAL goal",null)
B.V9=new A.ac("IS EMPTY (queue)","KUYRUK BO\u015e MU","TRUE when the queue holds nothing.","Kuyruk hi\xe7bir \u015fey tutmuyorsa TRUE olur.","WHILE NOT (line IS EMPTY)",null)
B.V0=new A.ac("NEW QUEUE","YEN\u0130 KUYRUK","A new, empty queue.","Yeni ve bo\u015f bir kuyruk.","SET line TO NEW QUEUE",null)
B.Tx=new A.ac("NEW MIN HEAP","YEN\u0130 M\u0130N \xd6NCEL\u0130K KUYRU\u011eU","A new, empty heap that always has its smallest number on top.","Yeni ve bo\u015f bir \xf6ncelik kuyru\u011fu; en k\xfc\xe7\xfck say\u0131 hep tepededir.","SET waiting TO NEW MIN HEAP",null)
B.Vd=new A.ac("NEW MAX HEAP","YEN\u0130 MAKS \xd6NCEL\u0130K KUYRU\u011eU","A new, empty heap that always has its largest number on top.","Yeni ve bo\u015f bir \xf6ncelik kuyru\u011fu; en b\xfcy\xfck say\u0131 hep tepededir.","SET best TO NEW MAX HEAP",null)
B.Ur=new A.ac("INSERT","\xd6NCEL\u0130K KUYRU\u011eUNA EKLE","Puts a number into a heap. The heap keeps its smallest (or largest) number on top, whatever order they come in.","\xd6ncelik kuyru\u011funa bir say\u0131 ekler. Say\u0131lar hangi s\u0131rayla gelirse gelsin, en k\xfc\xe7\xfck (ya da en b\xfcy\xfck) say\u0131 tepede kal\u0131r.","INSERT waiting cost",null)
B.UK=new A.ac("TAKE TOP","TEPEDEK\u0130N\u0130 AL","Takes the top number out of a heap and gives it: the smallest for a MIN heap, the largest for a MAX heap. An empty heap is an error: check IS EMPTY first.","Tepedeki say\u0131y\u0131 \xf6ncelik kuyru\u011fundan \xe7\u0131kar\u0131r ve verir: MIN i\xe7in en k\xfc\xe7\xfc\u011f\xfc, MAX i\xe7in en b\xfcy\xfc\u011f\xfc. Bo\u015f \xf6ncelik kuyru\u011fu hatad\u0131r: \xf6nce IS EMPTY ile kontrol et.","SET cheapest TO (waiting TAKE TOP)",null)
B.TG=new A.ac("TOP","TEPEYE BAK","The top number of a heap, without taking it out.","\xd6ncelik kuyru\u011funun tepesindeki say\u0131; \xe7\u0131karmadan bakar.","IF (best TOP) LESS THAN x",null)
B.Vj=new A.ac("SIZE (heap)","\xd6NCEL\u0130K KUYRU\u011eU BOYUTU","How many numbers a heap holds.","\xd6ncelik kuyru\u011funun ka\xe7 say\u0131 tuttu\u011fu.","IF (best SIZE) GREATER THAN k",null)
B.TY=new A.ac("IS EMPTY (heap)","\xd6NCEL\u0130K KUYRU\u011eU BO\u015e MU","TRUE when the heap holds nothing.","\xd6ncelik kuyru\u011fu hi\xe7bir \u015fey tutmuyorsa TRUE olur.","WHILE NOT (waiting IS EMPTY)",null)
B.TT=new A.ac("NODE VALUE (chain)","HALKA DE\u011eER\u0130","The number written on a link of a chain (linked list).","Bir zincirin (ba\u011fl\u0131 liste) halkas\u0131n\u0131n \xfczerindeki say\u0131.","SET total TO total PLUS (node NODE VALUE)",null)
B.TA=new A.ac("NEXT NODE","SONRAK\u0130 HALKA","The link after this one, or NOTHING at the end of the chain.","Bu halkadan sonraki halka; zincirin sonunda NOTHING.","SET node TO (node NEXT NODE)",null)
B.Ux=new A.ac("SET NEXT","SONRAK\u0130N\u0130 BA\u011eLA","Makes a link point to another link (or NOTHING): the chain is recoupled, nothing is copied. Slots: the link, the link it should point to.","Bir halkay\u0131 ba\u015fka bir halkay\u0131 (ya da NOTHING) g\xf6sterecek \u015fekilde ba\u011flar: zincir yeniden ba\u011flan\u0131r, hi\xe7bir \u015fey kopyalanmaz. Yuvalar: halka, g\xf6sterece\u011fi halka.","SET NEXT node prev",null)
B.Un=new A.ac("NODE VALUE (tree)","D\xdc\u011e\xdcM DE\u011eER\u0130","The number written on a node of a tree.","Bir a\u011fac\u0131n d\xfc\u011f\xfcm\xfcn\xfcn \xfczerindeki say\u0131.","IF (node NODE VALUE) GREATER THAN prev",null)
B.Vg=new A.ac("LEFT","SOL \xc7OCUK","The left child of a tree node, or NOTHING if it has none.","Bir a\u011fa\xe7 d\xfc\u011f\xfcm\xfcn\xfcn sol \xe7ocu\u011fu; yoksa NOTHING.","SET child TO (node LEFT)",null)
B.Ui=new A.ac("RIGHT","SA\u011e \xc7OCUK","The right child of a tree node, or NOTHING if it has none.","Bir a\u011fa\xe7 d\xfc\u011f\xfcm\xfcn\xfcn sa\u011f \xe7ocu\u011fu; yoksa NOTHING.","SET child TO (node RIGHT)",null)
B.Uj=new A.ac("NEIGHBORS","KOM\u015eULAR","The list of nodes you can go to from a node of a graph, in one step.","Bir \xe7izgede bir d\xfc\u011f\xfcmden tek ad\u0131mda gidilebilen d\xfc\u011f\xfcmlerin listesi.","FOR EACH next IN (metro NEIGHBORS here)",null)
B.U0=new A.ac("MARK","\u0130\u015eARETLE","Marks a node of a graph as visited, so a search does not come back to it.","Bir \xe7izge d\xfc\u011f\xfcm\xfcn\xfc ziyaret edilmi\u015f olarak i\u015faretler; b\xf6ylece arama ona geri d\xf6nmez.","MARK islands s",null)
B.V7=new A.ac("VISITED","Z\u0130YARET ED\u0130LD\u0130 M\u0130","TRUE when a node of the graph has been marked.","\xc7izgenin bir d\xfc\u011f\xfcm\xfc i\u015faretlenmi\u015fse TRUE olur.","IF NOT (islands VISITED next)",null)
B.Uu=new A.ac("NODE COUNT","D\xdc\u011e\xdcM SAYISI","How many nodes a graph has; they are numbered 0 to (NODE COUNT) MINUS 1.","\xc7izgenin ka\xe7 d\xfc\u011f\xfcm\xfc oldu\u011fu; d\xfc\u011f\xfcmler 0'dan (NODE COUNT) MINUS 1'e kadar numaral\u0131d\u0131r.","FOR s FROM 0 TO (islands NODE COUNT) BY 1",null)
B.TH=new A.ac("TEXT","MET\u0130N",'A fixed piece of text, shown in quotes. There is no keyboard: tap it to choose one of the texts the puzzle offers. "" is the empty text, the usual start for a text you build with JOIN.','Sabit bir metin; t\u0131rnak i\xe7inde g\xf6sterilir. Klavye yoktur: bulmacan\u0131n sundu\u011fu metinlerden birini se\xe7mek i\xe7in dokun. "" bo\u015f metindir; JOIN ile kurulan bir metnin ola\u011fan ba\u015flang\u0131c\u0131d\u0131r.','SET result TO ""',null)
B.UI=new A.ac("TEXT LENGTH","MET\u0130N UZUNLU\u011eU","How many letters a text has. Spaces and digits count as letters; the empty text has 0.","Bir metinde ka\xe7 harf oldu\u011funu verir. Bo\u015fluklar ve rakamlar da harf say\u0131l\u0131r; bo\u015f metnin uzunlu\u011fu 0'd\u0131r.","FOR i FROM 0 TO (word TEXT LENGTH)",null)
B.UV=new A.ac("LETTER AT","KONUMDAK\u0130 HARF","The one letter at a position of a text, as a text. Positions start at 0, like a list; a position outside the text is an error.","Metnin bir konumundaki tek harfi, yine metin olarak verir. Konumlar listedeki gibi 0'dan ba\u015flar; metnin d\u0131\u015f\u0131ndaki bir konum hatad\u0131r.",'IF (word LETTER AT i) EQUAL "a"',null)
B.Uh=new A.ac("JOIN","B\u0130RLE\u015eT\u0130R","Puts two texts together, the left one first. Neither text changes: the result is a new text.","\u0130ki metni, soldaki \xf6nce gelecek \u015fekilde u\xe7 uca ekler. \u0130ki metin de de\u011fi\u015fmez: sonu\xe7 yeni bir metindir.","SET result TO result JOIN (word LETTER AT i)",null)
B.Uw=new A.ac("PART OF TEXT","METN\u0130N PAR\xc7ASI","The letters of a text from a start position up to, but not including, an end position. Start 0 and end TEXT LENGTH give the whole text.","Metnin ba\u015flang\u0131\xe7 konumundan biti\u015f konumuna kadar olan harfleri verir; biti\u015f konumundaki harf dahil de\u011fildir. Ba\u015flang\u0131\xe7 0, biti\u015f TEXT LENGTH ise metnin tamam\u0131 \xe7\u0131kar.","SET first TO word PART OF TEXT 0 3","SET first TO word PART OF TEXT 0 3   (ilk \xfc\xe7 harf)")
B.TX=new A.ac("COMPARE TEXT","MET\u0130NLER\u0130 KAR\u015eILA\u015eTIR","Compares two texts letter by letter, in dictionary order: -1 when the left one comes first, 1 when the right one does, 0 when they are the same. A text comes before any longer text that starts with it. Capital letters come before small ones.","\u0130ki metni harf harf, s\xf6zl\xfck s\u0131ras\u0131yla kar\u015f\u0131la\u015ft\u0131r\u0131r: soldaki \xf6nce geliyorsa -1, sa\u011fdaki \xf6nce geliyorsa 1, ayn\u0131ysalar 0 verir. Bir metin, kendisiyle ba\u015flayan daha uzun her metinden \xf6nce gelir. B\xfcy\xfck harfler k\xfc\xe7\xfck harflerden \xf6nce gelir.","IF (a COMPARE TEXT b) LESS THAN 0",null)
B.U7=new A.ac("NUMBER AS TEXT","SAYIYI METNE \xc7EV\u0130R",'Writes a whole number as text, with a - in front of a negative one: 42 becomes "42".','Bir tam say\u0131y\u0131 metin olarak yazar; negatif say\u0131n\u0131n \xf6n\xfcne - koyar: 42, "42" olur.','SET label TO "n" JOIN (count NUMBER AS TEXT)',null)
B.UZ=new A.ac("TEXT AS NUMBER","METN\u0130 SAYIYA \xc7EV\u0130R","Reads a text made only of digits (with an optional - in front) as a number. Any other text gives NOTHING, so check with IS NOTHING before using the result.","Yaln\u0131zca rakamlardan olu\u015fan (ba\u015f\u0131nda iste\u011fe ba\u011fl\u0131 - olabilen) bir metni say\u0131 olarak okur. Ba\u015fka her metin NOTHING verir; sonucu kullanmadan \xf6nce IS NOTHING ile kontrol et.","SET n TO (word TEXT AS NUMBER)\nIF n IS NOT NOTHING\n  THEN  SET total TO total PLUS n",null)
B.UH=new A.ac("SORT","SIRALA","Puts a list of numbers in rising order, or a list of texts in dictionary order. It changes the list itself; equal items keep their order. Each comparison it makes costs one operation.","Bir say\u0131 listesini k\xfc\xe7\xfckten b\xfcy\xfc\u011fe, bir metin listesini s\xf6zl\xfck s\u0131ras\u0131na dizer. Listenin kendisini de\u011fi\u015ftirir; e\u015fit \xf6\u011feler kendi s\u0131ralar\u0131n\u0131 korur. Yapt\u0131\u011f\u0131 her kar\u015f\u0131la\u015ft\u0131rma bir i\u015flem say\u0131l\u0131r.","SORT scores",null)
B.Ut=new A.ac("COPY","KOPYALA","Makes a real copy of what one variable holds and puts it into another. Changing the copy leaves the original alone. SET would only give the same list a second name. A copy uses memory cells: one for the collection and one for each item.","Bir de\u011fi\u015fkenin tuttu\u011fu \u015feyin ger\xe7ek bir kopyas\u0131n\u0131 yapar ve ba\u015fka bir de\u011fi\u015fkene koyar. Kopyay\u0131 de\u011fi\u015ftirmek asl\u0131n\u0131 de\u011fi\u015ftirmez. SET ise ayn\u0131 listeye yaln\u0131zca ikinci bir ad verir. Kopya bellek h\xfccresi kullan\u0131r: koleksiyon i\xe7in bir, her \xf6\u011fe i\xe7in bir.","COPY scores TO sorted\nSORT sorted",null)
B.Ue=new A.ac("NEW DEQUE","YEN\u0130 \xc7\u0130FT U\xc7LU KUYRUK","A new, empty deque: a line you can add to and take from at both ends.","Yeni ve bo\u015f bir \xe7ift u\xe7lu kuyruk: iki ucundan da eklenip al\u0131nabilen bir s\u0131ra.","SET window TO NEW DEQUE",null)
B.V2=new A.ac("PUSH FRONT","\xd6NE EKLE","Adds a value at the front of a deque.","\xc7ift u\xe7lu kuyru\u011fun \xf6n\xfcne bir de\u011fer ekler.","PUSH FRONT window x",null)
B.Ud=new A.ac("PUSH BACK","ARKAYA EKLE","Adds a value at the back of a deque.","\xc7ift u\xe7lu kuyru\u011fun arkas\u0131na bir de\u011fer ekler.","PUSH BACK window x",null)
B.Uz=new A.ac("POP FRONT","\xd6NDEN AL","Takes the front value out of a deque and gives it. An empty deque is an error: check IS EMPTY first.","\xc7ift u\xe7lu kuyru\u011fun \xf6n\xfcndeki de\u011feri \xe7\u0131kar\u0131r ve verir. Bo\u015f kuyruk hatad\u0131r: \xf6nce IS EMPTY ile kontrol et.","SET oldest TO (window POP FRONT)",null)
B.U3=new A.ac("POP BACK","ARKADAN AL","Takes the back value out of a deque and gives it. An empty deque is an error: check IS EMPTY first.","\xc7ift u\xe7lu kuyru\u011fun arkas\u0131ndaki de\u011feri \xe7\u0131kar\u0131r ve verir. Bo\u015f kuyruk hatad\u0131r: \xf6nce IS EMPTY ile kontrol et.","SET newest TO (window POP BACK)",null)
B.UP=new A.ac("FRONT (deque)","\xd6NE BAK","The front value of a deque, without taking it out.","\xc7ift u\xe7lu kuyru\u011fun \xf6n\xfcndeki de\u011fer; \xe7\u0131karmadan bakar.","IF (window FRONT) LESS THAN x",null)
B.UA=new A.ac("BACK","ARKAYA BAK","The back value of a deque, without taking it out.","\xc7ift u\xe7lu kuyru\u011fun arkas\u0131ndaki de\u011fer; \xe7\u0131karmadan bakar.","WHILE (window BACK) LESS THAN x",null)
B.Ug=new A.ac("SIZE (deque)","\xc7\u0130FT U\xc7LU KUYRUK BOYUTU","How many values a deque holds.","\xc7ift u\xe7lu kuyrukta ka\xe7 de\u011fer oldu\u011funu verir.","IF (window SIZE) GREATER THAN k",null)
B.TS=new A.ac("IS EMPTY (deque)","\xc7\u0130FT U\xc7LU KUYRUK BO\u015e MU","TRUE when the deque holds nothing.","\xc7ift u\xe7lu kuyruk hi\xe7bir \u015fey tutmuyorsa TRUE olur.","WHILE NOT (window IS EMPTY)",null)
B.TQ=new A.ac("MAKE PAIR","\xc7\u0130FT YAP","Ties two values together as one value, a pair: a name and its score, a position and its height. A pair never changes after it is made.","\u0130ki de\u011feri tek bir de\u011fer olarak, bir \xe7ift halinde ba\u011flar: bir ad ile puan\u0131, bir konum ile y\xfcksekli\u011fi. \xc7ift, yap\u0131ld\u0131ktan sonra de\u011fi\u015fmez.","APPEND result (name MAKE PAIR score)",null)
B.Up=new A.ac("FIRST","\xc7\u0130FT\u0130N \u0130LK\u0130","The first value of a pair.","Bir \xe7iftin ilk de\u011feri.","SET name TO (entry FIRST)",null)
B.UD=new A.ac("SECOND","\xc7\u0130FT\u0130N \u0130K\u0130NC\u0130S\u0130","The second value of a pair.","Bir \xe7iftin ikinci de\u011feri.","IF (entry SECOND) GREATER THAN best",null)
